def parse_points(text):
    out = {}
    # 先按顶层分隔切成 "key=[...]" 的片段
    seqs = re.finditer(
        r'([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s*=\s*\[', text)
    # 找到每个 [ 的位置
    brackets = [(m.group(1), m.end()) for m in seqs]
    
    for i, (key, start) in enumerate(brackets):
        if i + 1 < len(brackets):
            # 下一个 [ 之前的位置就是当前 ] 的位置
            end = text.rfind(']', start, brackets[i + 1][1])
        else:
            end = text.rfind(']', start)
        body = text[start:end] if end != -1 else text[start:]
        pts = re.findall(
            r'x\s*=\s*([-+eE\d.]+)\s*,\s*y\s*=\s*([-+eE\d.]+)', body)
        out[float(key)] = [(float(x), float(y)) for x, y in pts]
    return out

